-- noinspection SqlNoDataSourceInspectionForFile
-- Verification for the eight seed values inspected before the BF-03 encoding repair.
SET NOCOUNT ON;
IF NOT EXISTS (SELECT 1 FROM dbo.[articles] WHERE id = 1 AND CONVERT(VARBINARY(MAX), [title]) = 0x4E006700B001DD1E690020006400E2006E0020006B006800750020004200AF1E630020004800E00020006B006800D11E6E0020006B006800D51E20007600EC0020006E006700AD1E7000200073006100750020006200E3006F00)
    THROW 51100, 'UTF-8 repair verification failed: articles.title id=1', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.[appeal_criteria] WHERE id = 1 AND CONVERT(VARBINARY(MAX), [reason]) = 0x4200E00069002000110103016E00670020006E006700610079002000740072006F006E00670020006E006700E000790020006200E3006F0020001101D51E20006200D91E2C0020006B006800F4006E006700200063006800AD1E6D0020006800A1016E0020006200E1006F0020006B006800E10063002E00)
    THROW 51101, 'UTF-8 repair verification failed: appeal_criteria.reason id=1', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.[criteria] WHERE id = 1 AND CONVERT(VARBINARY(MAX), [name]) = 0x5400ED006E006800200070006800E1007400200068006900C71E6E002C0020001101D91E63002000710075007900C11E6E00)
    THROW 51102, 'UTF-8 repair verification failed: criteria.name id=1', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.[criteria] WHERE id = 2 AND CONVERT(VARBINARY(MAX), [name]) = 0x1001D91E20006B006800F30020006B006800690020007400E100630020006E00670068006900C71E7000)
    THROW 51103, 'UTF-8 repair verification failed: criteria.name id=2', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.[criteria] WHERE id = 3 AND CONVERT(VARBINARY(MAX), [name]) = 0x43006800A51E740020006C00B001E31E6E006700200076006900BF1E74002C00200074007200EC006E00680020006200E0007900)
    THROW 51104, 'UTF-8 repair verification failed: criteria.name id=3', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.[criteria] WHERE id = 4 AND CONVERT(VARBINARY(MAX), [name]) = 0x5400ED006E006800200074006800DD1E690020007300F11E)
    THROW 51105, 'UTF-8 repair verification failed: criteria.name id=4', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.[scoring_attempt_details] WHERE id = 3 AND CONVERT(VARBINARY(MAX), [comment]) = 0x56006900BF1E740020007200F50020007200E0006E0067002C0020006300F30020006E006800E2006E00200063006800E91E6E0067002E00)
    THROW 51106, 'UTF-8 repair verification failed: scoring_attempt_details.comment id=3', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.[scoring_attempt_details] WHERE id = 4 AND CONVERT(VARBINARY(MAX), [comment]) = 0x100103016E006700200063006800AD1E6D0020006800A1016E0020006200E1006F0020006B006800E10063002000310020006E006700E00079002E00)
    THROW 51107, 'UTF-8 repair verification failed: scoring_attempt_details.comment id=4', 1;
PRINT 'PASS: all 8 appeal text values contain the expected Vietnamese Unicode characters.';
